78: void SingleApplicationPrivate::genBlockServerName( int timeout )
79: {
80:     QCryptographicHash appData( QCryptographicHash::Sha256 );
81: #if QT_VERSION < QT_VERSION_CHECK(6, 4, 0)
82:     appData.addData( "SingleApplication", 17 );
83: #else
84:     appData.addData( QByteArrayView("SingleApplication", 17) );
85: #endif
86:     appData.addData( SingleApplication::app_t::applicationName().toUtf8() );
87:     appData.addData( SingleApplication::app_t::organizationName().toUtf8() );
88:     appData.addData( SingleApplication::app_t::organizationDomain().toUtf8() );
89: 
90:     if( ! (options & SingleApplication::Mode::ExcludeAppVersion) ) {
91:         appData.addData( SingleApplication::app_t::applicationVersion().toUtf8() );
92:     }
93: 
94:     if( ! (options & SingleApplication::Mode::ExcludeAppPath) ) {
95: #ifdef Q_OS_WIN
96:         appData.addData( SingleApplication::app_t::applicationFilePath().toLower().toUtf8() );
97: #else
98:         appData.addData( SingleApplication::app_t::applicationFilePath().toUtf8() );
99: #endif
100:     }
101: 
102:     // User level block requires a user specific data in the hash
103:     if( options & SingleApplication::Mode::User ) {
104: #ifdef Q_OS_WIN
105:         Q_UNUSED(timeout);
106:         wchar_t username [ UNLEN + 1 ];
107:         // Specifies size of the buffer on input
108:         DWORD usernameLength = UNLEN + 1;
109:         if( GetUserNameW( username, &usernameLength ) ) {
110:             appData.addData( QString::fromWCharArray(username).toUtf8() );
111:         } else {
112:             appData.addData( QStandardPaths::standardLocations( QStandardPaths::HomeLocation ).join("").toUtf8() );
113:         }
114: #endif
115: #ifdef Q_OS_UNIX
116:         QProcess process;
117:         process.start( "whoami" );
118:         if( process.waitForFinished( timeout ) &&
119:             process.exitCode() == QProcess::NormalExit) {
120:             appData.addData( process.readLine() );
121:         } else {
122:             appData.addData(
123:                 QDir(
124:                     QStandardPaths::standardLocations( QStandardPaths::HomeLocation ).first()
125:                 ).absolutePath().toUtf8()
126:             );
127:         }
128: #endif
129:     }
130: 
131:     // Replace the backslash in RFC 2045 Base64 [a-zA-Z0-9+/=] to comply with
132:     // server naming requirements.
133:     blockServerName = appData.result().toBase64().replace("/", "_");
134: }
