136: void SingleApplicationPrivate::startPrimary( bool resetMemory )
137: {
138:     Q_Q(SingleApplication);
139: 
140: #ifdef Q_OS_UNIX
141:     // Handle any further termination signals to ensure the
142:     // QSharedMemory block is deleted even if the process crashes
143:     crashHandler();
